pub const fn peer_id(&self) -> Option<PeerId> {
    match self {
        Self::Gossip(_, gossip_id) => Some(gossip_id.source),
        Self::Requested(peer_id) => Some(*peer_id),
        Self::Api(_) | Self::BackSync | Self::ExecutionLayer | Self::Own => None,
    }
