pub const fn subnet_id(&self) -> Option<SubnetId> {
    match self {
        Self::Gossip(subnet_id, _) => Some(*subnet_id),
        Self::Api(_)
        | Self::BackSync
        | Self::ExecutionLayer
        | Self::Own
        | Self::Requested(_) => None,
    }
}

